tool_input.command:
cd /app && cat > /tmp/qemu-setup.expect << 'EOFEXPECT'
#!/usr/bin/expect -f
set timeout 60
spawn telnet localhost 2222
expect {
  "localhost login:" {
    send "root\r"
    expect {
      "Password:" {
        send "\r"
        expect "#"
      }
    }
  }
  timeout {
    puts "Timeout waiting for login prompt"
    exit 1
  }
}
send "passwd root\r"
expect "New password:"
send "password123\r"
expect "Retype password:"
send "password123\r"
expect "#"
send "rc-service sshd start\r"
expect "#"
send "exit\r"
EOFEXPECT
chmod +x /tmp/qemu-setup.expect
/tmp/qemu-setup.expect
